const fs = require("node:fs"),
  path = require("node:path");
const root = path.resolve(__dirname, "..");
const data = {
  catalogs: Object.fromEntries(
    [
      ["pt-BR", "pt_BR"],
      ["en", "en"],
    ].map(([locale, folder]) => [
      locale,
      JSON.parse(
        fs.readFileSync(
          path.join(root, "_locales", folder, "messages.json"),
          "utf8",
        ),
      ),
    ]),
  ),
  literals: JSON.parse(
    fs.readFileSync(path.join(root, "i18n/literal-keys.json"), "utf8"),
  ),
};
fs.writeFileSync(
  path.join(root, "i18n.js"),
  "// Generated by scripts/build-i18n.cjs. Edit i18n/runtime.js and the catalogs.\n" +
    fs
      .readFileSync(path.join(root, "i18n/runtime.js"), "utf8")
      .replace("__SUPER_I18N_DATA__", JSON.stringify(data)),
);
